import org.springframework.http.server.ServletServerHttpRequest;
import org.springframework.web.util.UriComponentsBuilder;
import org.springframework.web.util.UriComponents;
import org.springframework.http.HttpHeaders;

static UriComponentsBuilder getBuilder() {
    HttpServletRequest request = getCurrentRequest();
    UriComponentsBuilder builder = UriComponentsBuilder.fromHttpRequest(new ServletServerHttpRequest(request));

    String scheme = builder.build().getScheme(); // Get the scheme if already set
    String host = builder.build().getHost(); // Get the host if already set

    // special case handling for X-Forwarded-Ssl:
    // apply it, but only if X-Forwarded-Proto is unset.
    String proto = request.getHeader("X-Forwarded-Proto");
    String forwardedSsl = request.getHeader("X-Forwarded-Ssl");
    ForwardedHeader forwarded = ForwardedHeader.of(request.getHeader(ForwardedHeader.NAME));

    if (!hasText(proto) && hasText(forwardedSsl) && forwardedSsl.equalsIgnoreCase("on")) {
        if (!hasText(scheme)) {
            builder.scheme("https");
        }
    } else if (forwarded != null && hasText(forwarded.getProto()) && forwardedSsl != null && forwardedSsl.equalsIgnoreCase("on")) {
        if (!hasText(scheme)) {
            builder.scheme(forwarded.getProto());
        }
    }

    // Update the host and port if necessary
    if (forwarded != null && hasText(forwarded.getHost())) {
        builder.host(forwarded.getHost());
    }

    List<String> forwardedPorts = HttpHeaders.parseForwardedFor(request.getHeader(HttpHeaders.X_FORWARDED_PORT));
    if (forwardedPorts != null && !forwardedPorts.isEmpty()) {
        builder.port(Integer.parseInt(forwardedPorts.get(0)));
    }

    return builder;
}

